  // body with the head to the right and a short tail to the left, so the bird reads as flying right
  const GULL_BODY = "M-1.9 .15C-1.4 -.2 -.3 -.45 .6 -.4C1.1 -.75 1.75 -.7 1.95 -.3L2.5 -.15L1.95 .05" +
                    "C1.7 .45 .6 .6 -.3 .5L-1.6 .7L-1.4 .35Z";
