            const [, x, y] = track(FIN_KEYS, t);
            const xfm = `translate(${x.toFixed(2)} ${y.toFixed(2)})`;
            this._fin.setAttribute("transform", xfm); this._fin.setAttribute("visibility", "visible");
            this._reflFin.setAttribute("transform", xfm); this._reflFin.setAttribute("visibility", "visible");
